import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function requiredText(value: unknown, max: number, label: string): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값을 입력해 주세요.');
  }
  if (value.length > max) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값은 ' + max + '자 이하로 입력해 주세요.');
  }
  return value;
}

function optionalText(value: unknown, max: number, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || value.length > max) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값은 ' + max + '자 이하의 글자로 입력해 주세요.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr02003Controller {
  @Post('/config-settings')
  @HttpCode(200)
  async createConfigSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const settingArea = requiredText(data['settingArea'], 50, '설정 영역');
    const settingKey = requiredText(data['settingKey'], 100, '설정 키');
    const settingValue = requiredText(data['settingValue'], 1000, '설정 값');
    const appliedFrom = requiredText(data['appliedFrom'], 10, '적용 시작일');
    if (!DATE_PATTERN.test(appliedFrom)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '적용 시작일은 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const description = optionalText(data['description'], 500, '설명');

    // TODO(질문): 마감된 기간의 기준 변경 거부(422 CONFIG_PERIOD_CLOSED)와 변경 이력 기록(공통 P15)은 마감 기간 출처가 없어 구현하지 못했다.
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT config_setting_id AS "configSettingId" FROM config_setting WHERE setting_area = :settingArea AND setting_key = :settingKey AND applied_from = CAST(:appliedFrom AS date)',
        { settingArea, settingKey, appliedFrom },
      );
      if (found.length > 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '같은 영역·키·적용 시작일의 설정이 이미 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO config_setting (setting_area, setting_key, setting_value, applied_from, description, created_at, updated_at) VALUES (:settingArea, :settingKey, :settingValue, CAST(:appliedFrom AS date), :description, now(), now()) RETURNING config_setting_id AS "configSettingId"',
        { settingArea, settingKey, settingValue, appliedFrom, description },
      );
      return rows[0];
    });
  }
}

