import { useState } from 'react';
import { Band, Badge, DataTable, DateInput, DateText, Drawer, Field, Filters, Form, Pager, Pairs, TextInput, Tiles, call, useData } from '../kit';
import type { PageProps, Page, Row } from '../kit';

export default function FnSfr02003Page({ role, notify }: PageProps) {
  const [areaInput, setAreaInput] = useState('');
  const [area, setArea] = useState('');
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [selected, setSelected] = useState<Row | null>(null);
  const [settingArea, setSettingArea] = useState('');
  const [settingKey, setSettingKey] = useState('');
  const [settingValue, setSettingValue] = useState('');
  const [appliedFrom, setAppliedFrom] = useState('');
  const [description, setDescription] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/config-settings', role, undefined, { settingArea: area, page, size: 20 }),
    [area, page, role],
  );
  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;

  function openCreate() {
    setSettingArea('');
    setSettingKey('');
    setSettingValue('');
    setAppliedFrom('');
    setDescription('');
    setCreating(true);
  }

  async function submit() {
    if (!settingArea.trim() || !settingKey.trim() || !settingValue.trim() || !appliedFrom) {
      throw new Error('설정 영역, 설정 키, 설정 값, 적용 시작일을 모두 입력해 주세요.');
    }
    await call('POST', '/config-settings', role, {
      settingArea,
      settingKey,
      settingValue,
      appliedFrom,
      description,
    });
    notify('기준 설정을 등록했습니다.');
    setCreating(false);
    setPage(0);
    list.reload();
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>등록된 기준</h2>
        <Tiles items={[['전체 건수', total]]} />
      </section>
      <section className="box span-8">
        <h2>기준 설정 목록</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setArea(areaInput);
          }}
          onReset={() => {
            setAreaInput('');
            setArea('');
            setPage(0);
          }}
        >
          <Field label="설정 영역">
            <TextInput value={areaInput} onChange={setAreaInput} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={openCreate}>기준 등록</button>
        </Band>
        <DataTable
          rows={rows}
          onRowClick={(row) => setSelected(row)}
          empty="등록된 기준 설정이 없습니다."
          columns={[
            { key: 'settingArea', label: '설정 영역', render: (r) => <Badge value={r['settingArea']} /> },
            { key: 'settingKey', label: '설정 키' },
            { key: 'settingValue', label: '설정 값' },
            { key: 'appliedFrom', label: '적용 시작일', render: (r) => <DateText value={r['appliedFrom']} /> },
          ]}
        />
        <Pager page={page} size={20} total={total} onPage={setPage} />
      </section>
      {selected && (
        <Drawer title="기준 설정 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['설정 영역', String(selected['settingArea'] ?? '')],
              ['설정 키', String(selected['settingKey'] ?? '')],
              ['설정 값', String(selected['settingValue'] ?? '')],
              ['적용 시작일', <DateText value={selected['appliedFrom']} />],
            ]}
          />
        </Drawer>
      )}
      {creating && (
        <Drawer title="기준 설정 등록" onClose={() => setCreating(false)}>
          <Form onSubmit={submit} submit="등록">
            <Field label="설정 영역" required>
              <TextInput value={settingArea} onChange={setSettingArea} />
            </Field>
            <Field label="설정 키" required>
              <TextInput value={settingKey} onChange={setSettingKey} />
            </Field>
            <Field label="설정 값" required wide>
              <TextInput value={settingValue} onChange={setSettingValue} multiline />
            </Field>
            <Field label="적용 시작일" required>
              <DateInput value={appliedFrom} onChange={setAppliedFrom} />
            </Field>
            <Field label="설명" wide>
              <TextInput value={description} onChange={setDescription} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
